#!/bin/sh
# Regra da AP2 (AGENTS.md, seção 5): todo commit, inclusive merge local, termina com
# os trailers "Agent:" e "Spec:", e a spec citada precisa existir no repositório.
# Ativado por `git config core.hooksPath .githooks` (o `pnpm install` já faz).

mensagem="$1"

recusar() {
  echo "commit recusado: $1" >&2
  echo "  A mensagem precisa terminar com:" >&2
  echo "    Agent: <ferramenta>/<modelo>   (ou: none)" >&2
  echo "    Spec: SPEC/AAAA-MM-DD-<parte>.md" >&2
  echo "  Veja AGENTS.md, seção 5." >&2
  exit 1
}

grep -qE '^Agent: .+' "$mensagem" || recusar "falta o trailer Agent:"
spec=$(grep -m1 -E '^Spec: .+' "$mensagem" | sed -E 's/^Spec: *//; s/[[:space:]]+$//')
[ -n "$spec" ] || recusar "falta o trailer Spec:"
[ -f "$spec" ] || recusar "a spec \"$spec\" não existe no repositório"
exit 0
#!/bin/sh
# Regra da AP2 (AGENTS.md, seção 2): nada de commit direto na main.
# Ativado por `git config core.hooksPath .githooks` (o `pnpm install` já faz).

if [ "$(git symbolic-ref --short HEAD 2>/dev/null)" = "main" ]; then
  echo "commit recusado: não se commita na main. Crie uma branch a partir dela:" >&2
  echo "  git switch -c feat/<slug>" >&2
  exit 1
fi
exit 0
import { defineConfig, devices } from "@playwright/test";

import { SUPABASE_LOCAL } from "./tests/support/supabase-local";

// Porta própria para não reaproveitar um `pnpm dev` apontando para outro banco.
const PORT = Number(process.env.E2E_PORT ?? 3100);
const baseURL = `http://localhost:${PORT}`;
const TMDB_FALSO_PORTA = 4010;

export default defineConfig({
  testDir: "./tests/e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? "github" : "list",
  use: {
    baseURL,
    trace: "on-first-retry",
    // Sem animações por padrão: o globo do "Me surpreenda" girando em vários navegadores
    // headless ao mesmo tempo consome a CPU. O teste da animação liga o movimento de volta.
    reducedMotion: "reduce",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: [
    {
      // TMDB falso: respostas determinísticas, sem depender da internet.
      command: `node tests/e2e/tmdb-falso/servidor.mjs ${TMDB_FALSO_PORTA}`,
      url: `http://127.0.0.1:${TMDB_FALSO_PORTA}/3/discover/movie`,
      reuseExistingServer: false,
      timeout: 30_000,
    },
    {
      // No CI o build já foi feito com as variáveis do Supabase local. Localmente o
      // build é refeito, porque as variáveis NEXT_PUBLIC_* são embutidas no build.
      command: process.env.CI
        ? `pnpm start --port ${PORT}`
        : `pnpm build && pnpm start --port ${PORT}`,
      url: `${baseURL}/api/health`,
      reuseExistingServer: false,
      timeout: 300_000,
      env: {
        NEXT_PUBLIC_SUPABASE_URL: SUPABASE_LOCAL.url,
        NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: SUPABASE_LOCAL.publishableKey,
        TMDB_READ_TOKEN: "token-e2e",
        TMDB_API_URL: `http://127.0.0.1:${TMDB_FALSO_PORTA}/3`,
        IMAGENS_SEM_OTIMIZACAO: "1",
      },
    },
  ],
});
import { z } from "zod";

const publicSchema = z.object({
  NEXT_PUBLIC_SUPABASE_URL: z.url(),
  NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: z.string().min(1),
});

const serverSchema = publicSchema.extend({
  TMDB_READ_TOKEN: z.string().min(1),
  TMDB_API_URL: z.url().default("https://api.themoviedb.org/3"),
});

export type PublicEnv = z.infer<typeof publicSchema>;
export type ServerEnv = z.infer<typeof serverSchema>;

export class EnvError extends Error {
  constructor(public readonly variables: string[]) {
    super(
      `Variáveis de ambiente ausentes ou inválidas: ${variables.join(", ")}. ` +
        "Confira o arquivo .env.local (veja .env.example).",
    );
    this.name = "EnvError";
  }
}

function parse<T extends z.ZodType>(schema: T, source: Record<string, string | undefined>) {
  const result = schema.safeParse(source);
  if (!result.success) {
    const variables = [...new Set(result.error.issues.map((issue) => String(issue.path[0])))];
    throw new EnvError(variables);
  }
  return result.data as z.infer<T>;
}

export function parsePublicEnv(source: Record<string, string | undefined>): PublicEnv {
  return parse(publicSchema, source);
}

export function parseServerEnv(source: Record<string, string | undefined>): ServerEnv {
  return parse(serverSchema, source);
}

let cachedPublicEnv: PublicEnv | undefined;

/**
 * Variáveis seguras para o navegador. As referências a `process.env.NEXT_PUBLIC_*`
 * precisam ser literais para o Next.js conseguir embuti-las no bundle do cliente.
 */
export function getPublicEnv(): PublicEnv {
  cachedPublicEnv ??= parsePublicEnv({
    NEXT_PUBLIC_SUPABASE_URL: process.env.NEXT_PUBLIC_SUPABASE_URL,
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
  });
  return cachedPublicEnv;
}
// Garante que segredos do servidor não vazaram para o bundle do navegador.
// Uso: depois de `pnpm build`, rode `pnpm check:secrets` com as mesmas variáveis do build.
import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";

// Como o `next build`, lê os arquivos .env locais sem sobrescrever variáveis já definidas.
for (const file of [".env.local", ".env"]) {
  try {
    process.loadEnvFile(file);
  } catch {
    // Arquivo ausente (ex.: no CI, onde as variáveis vêm do ambiente).
  }
}

const SECRET_VARIABLES = ["TMDB_READ_TOKEN"];
const STATIC_DIR = ".next/static";

async function* walk(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(path);
    else yield path;
  }
}

const secrets = SECRET_VARIABLES.map((name) => [name, process.env[name]]).filter(
  ([, value]) => value && value.length >= 4,
);

if (secrets.length === 0) {
  console.error(`Defina ${SECRET_VARIABLES.join(", ")} para verificar o build.`);
  process.exit(1);
}

const leaks = [];
for await (const file of walk(STATIC_DIR)) {
  const content = await readFile(file, "utf8");
  for (const [name, value] of secrets) {
    if (content.includes(value)) leaks.push(`${name} encontrado em ${file}`);
  }

